using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

namespace BOW.Game
{
    /// <summary>
    /// The menu's look: glassy dark buttons with a neon rim and glow (gold for the main action, cyan for the rest),
    /// icons, the logo and the backdrop fade. Matches the logo and the main-menu concept (Docs/concepts/29, 31).
    /// All art is generated by <see cref="MenuArt"/> except the logo (Resources/UI/Menu/logo).
    /// </summary>
    public static class MenuStyle
    {
        public static readonly Color Gold = new Color(1f, 0.74f, 0.16f);
        public static readonly Color Cyan = new Color(0.22f, 0.9f, 1f);
        public static readonly Color Red = new Color(1f, 0.32f, 0.3f);
        public static readonly Color Body = new Color(0.07f, 0.11f, 0.2f, 0.94f);
        public static readonly Color TextMuted = new Color(0.72f, 0.8f, 0.9f);

        private const int BodySize = 128, BodyRadius = 30, BodyRim = 4, BodySlice = 36;
        private const int GlowSize = 192, GlowSpread = 34, GlowSlice = GlowSpread + BodySlice;

        private static Sprite _fill, _rim, _glow, _fade, _logo, _disc, _ring;
        private static bool _logoTried;
        private static readonly Dictionary<MenuIcon, Sprite> Icons = new Dictionary<MenuIcon, Sprite>();

        /// <summary>No domain reload between Play sessions: drop sprites whose textures did not survive.</summary>
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        private static void ResetCaches()
        {
            _fill = _rim = _glow = _fade = _logo = _disc = _ring = null;
            _logoTried = false;
            Icons.Clear();
        }

        // ----- Sprites -----

        private static void BuildBody()
        {
            MenuArt.Body(BodySize, BodyRadius, BodyRim, out var fill, out var shade, out var rim);
            _fill = Sliced(ToTexture("Menu Button Fill", BodySize, BodySize, fill, shade), BodySlice);
            _rim = Sliced(ToTexture("Menu Button Rim", BodySize, BodySize, rim, null), BodySlice);
        }

        internal static Sprite Fill { get { if (_fill == null) BuildBody(); return _fill; } }
        internal static Sprite Rim { get { if (_rim == null) BuildBody(); return _rim; } }

        private static Sprite Glow
        {
            get
            {
                if (_glow != null) return _glow;
                var alpha = MenuArt.Glow(GlowSize, GlowSpread, BodyRadius);
                return _glow = Sliced(ToTexture("Menu Button Glow", GlowSize, GlowSize, alpha, null), GlowSlice);
            }
        }

        private static Sprite Fade
        {
            get
            {
                if (_fade != null) return _fade;
                const int width = 256;
                var alpha = MenuArt.FadeRight(width);
                var tex = ToTexture("Menu Fade", width, 1, alpha, null);
                return _fade = Sprite.Create(tex, new Rect(0, 0, width, 1), new Vector2(0.5f, 0.5f), 100f);
            }
        }

        public static Sprite Icon(MenuIcon icon)
        {
            if (Icons.TryGetValue(icon, out var sprite) && sprite != null) return sprite;
            const int size = 128;
            var tex = ToTexture("Menu Icon " + icon, size, size, MenuArt.Icon(icon, size), null);
            tex.mipMapBias = -0.5f;
            sprite = Sprite.Create(tex, new Rect(0, 0, size, size), new Vector2(0.5f, 0.5f), 100f);
            Icons[icon] = sprite;
            return sprite;
        }

        /// <summary>The game's logo, or null if the file is missing.</summary>
        public static Sprite Logo
        {
            get
            {
                if (_logoTried) return _logo;
                _logoTried = true;
                _logo = Resources.Load<Sprite>("UI/Menu/logo");
                if (_logo == null)
                {
                    var tex = Resources.Load<Texture2D>("UI/Menu/logo");
                    if (tex != null) _logo = Sprite.Create(tex, new Rect(0, 0, tex.width, tex.height), new Vector2(0.5f, 0.5f), 100f);
                }
                return _logo;
            }
        }

        private static Texture2D ToTexture(string name, int width, int height, float[] alpha, float[] shade)
        {
            var tex = new Texture2D(width, height, TextureFormat.RGBA32, true)
            {
                name = name,
                wrapMode = TextureWrapMode.Clamp,
                filterMode = FilterMode.Trilinear,
                hideFlags = HideFlags.DontSave,
            };
            var pixels = new Color32[width * height];
            for (int i = 0; i < pixels.Length; i++)
            {
                byte v = shade != null ? (byte)(shade[i] * 255f) : (byte)255;
                pixels[i] = new Color32(v, v, v, (byte)(alpha[i] * 255f));
            }
            tex.SetPixels32(pixels);
            tex.Apply(true, true);
            return tex;
        }

        // Round art for portraits, drawn large (and mipmapped) so it stays smooth at any size on screen.
        private const int RoundSize = 512;
        private const float RingInner = 0.91f;   // ring's inner edge, as a fraction of its radius
        private const float PortraitInset = 0.03f; // the portrait's clip sits under the ring: 0.94 of the radius

        private static Sprite Disc => _disc != null ? _disc : (_disc = Round("Menu Disc", 0f));
        private static Sprite RingSprite => _ring != null ? _ring : (_ring = Round("Menu Ring", RingInner));

        /// <summary>A white anti-aliased disc, or a ring when <paramref name="inner"/> (fraction of the radius) is above 0.</summary>
        private static Sprite Round(string name, float inner)
        {
            var alpha = new float[RoundSize * RoundSize];
            float c = RoundSize * 0.5f, r = c - 2f, ri = r * inner;
            for (int y = 0; y < RoundSize; y++)
            for (int x = 0; x < RoundSize; x++)
            {
                float dx = x + 0.5f - c, dy = y + 0.5f - c;
                float d = Mathf.Sqrt(dx * dx + dy * dy);
                float a = Mathf.Clamp01(r - d + 0.5f);
                if (inner > 0f) a *= Mathf.Clamp01(d - ri + 0.5f);
                alpha[y * RoundSize + x] = a;
            }
            var tex = ToTexture(name, RoundSize, RoundSize, alpha, null);
            return Sprite.Create(tex, new Rect(0, 0, RoundSize, RoundSize), new Vector2(0.5f, 0.5f), 100f, 0, SpriteMeshType.FullRect);
        }

        private static Sprite Sliced(Texture2D tex, int border) =>
            Sprite.Create(tex, new Rect(0, 0, tex.width, tex.height), new Vector2(0.5f, 0.5f), 100f, 0, SpriteMeshType.FullRect,
                new Vector4(border, border, border, border));

        // ----- Pieces -----

        private static Image SlicedImage(RectTransform rt, Sprite sprite, Color color)
        {
            var image = rt.gameObject.AddComponent<Image>();
            image.sprite = sprite;
            image.type = UnityEngine.UI.Image.Type.Sliced;
            image.color = color;
            return image;
        }

        /// <summary>Dark fade from the left edge, so the menu column reads over the live match behind it.</summary>
        public static void LeftFade(RectTransform parent, float width, float strength)
        {
            var rt = UiFactory.Rect("Left Fade", parent, new Vector2(0f, 0.5f), new Vector2(0f, 0.5f), Vector2.zero, new Vector2(width, 0f));
            rt.anchorMin = new Vector2(0f, 0f);
            rt.anchorMax = new Vector2(0f, 1f);
            rt.sizeDelta = new Vector2(width, 0f);
            var image = rt.gameObject.AddComponent<Image>();
            image.sprite = Fade;
            image.color = new Color(0.01f, 0.02f, 0.05f, strength);
            image.raycastTarget = false;
        }

        /// <summary>A framed panel for dialogs: dark glass, a rim and a soft glow in <paramref name="accent"/>.</summary>
        public static void Panel(RectTransform rt, Color accent)
        {
            var glow = UiFactory.Stretch("Glow", rt);
            glow.offsetMin = new Vector2(-GlowSpread, -GlowSpread);
            glow.offsetMax = new Vector2(GlowSpread, GlowSpread);
            SlicedImage(glow, Glow, new Color(accent.r, accent.g, accent.b, 0.35f)).raycastTarget = false;
            SlicedImage(UiFactory.Stretch("Fill", rt), Fill, new Color(0.05f, 0.08f, 0.15f, 0.97f));
            SlicedImage(UiFactory.Stretch("Rim", rt), Rim, accent).raycastTarget = false;
        }

        /// <summary>Title text for dialogs: bold italic with a drop shadow.</summary>
        public static Text Heading(RectTransform rt, string text, int size, Color color, TextAnchor anchor = TextAnchor.MiddleCenter)
        {
            var label = UiFactory.Text(rt, text, size, color, anchor, outline: false);
            UiFactory.UseDisplayFont(label);
            var shadow = rt.gameObject.AddComponent<Shadow>();
            shadow.effectColor = new Color(0f, 0f, 0f, 0.7f);
            shadow.effectDistance = new Vector2(0f, -4f);
            return label;
        }

        /// <summary>
        /// A menu button: glow, glass body, rim, an optional icon on the left and a bold italic label.
        /// <paramref name="glowStrength"/> 0 hides the glow (secondary buttons); the main action uses about 0.6.
        /// </summary>
        public static MenuButton Button(Transform parent, string label, MenuIcon? icon, Color accent, Vector2 anchor, Vector2 pivot,
            Vector2 position, Vector2 size, float glowStrength, Action onClick)
        {
            var rt = UiFactory.Rect(label, parent, anchor, pivot, position, size);
            var group = rt.gameObject.AddComponent<CanvasGroup>();

            // Content sits in a child so press/slide animation can move it without fighting the layout position.
            var content = UiFactory.Stretch("Content", rt);

            Image glow = null;
            if (glowStrength > 0f)
            {
                var glowRect = UiFactory.Stretch("Glow", content);
                glowRect.offsetMin = new Vector2(-GlowSpread, -GlowSpread);
                glowRect.offsetMax = new Vector2(GlowSpread, GlowSpread);
                glow = SlicedImage(glowRect, Glow, new Color(accent.r, accent.g, accent.b, glowStrength));
                glow.raycastTarget = false;
            }

            var body = SlicedImage(UiFactory.Stretch("Body", content), Fill, Body);
            var rim = SlicedImage(UiFactory.Stretch("Rim", content), Rim, accent);
            rim.raycastTarget = false;

            float h = size.y;
            float textLeft = h * 0.36f;
            bool iconOnly = icon.HasValue && string.IsNullOrEmpty(label);
            Image iconImage = null;
            if (icon.HasValue)
            {
                float iconSize = h * 0.5f;
                var iconAnchor = iconOnly ? new Vector2(0.5f, 0.5f) : new Vector2(0f, 0.5f);
                var iconRect = UiFactory.Rect("Icon", content, iconAnchor, new Vector2(0.5f, 0.5f), new Vector2(iconOnly ? 0f : h * 0.56f, 0f), new Vector2(iconSize, iconSize));
                iconImage = iconRect.gameObject.AddComponent<Image>();
                iconImage.sprite = Icon(icon.Value);
                iconImage.color = accent;
                iconImage.raycastTarget = false;
                iconImage.preserveAspect = true;
                textLeft = h * 0.98f;
            }

            var textRect = UiFactory.Stretch("Label", content);
            textRect.offsetMin = new Vector2(textLeft, 0f);
            textRect.offsetMax = new Vector2(-h * 0.3f, 0f);
            var text = Heading(textRect, label, Mathf.RoundToInt(h * 0.42f), Color.white, icon.HasValue ? TextAnchor.MiddleLeft : TextAnchor.MiddleCenter);
            text.resizeTextForBestFit = true;
            text.resizeTextMinSize = Mathf.RoundToInt(h * 0.25f);
            text.resizeTextMaxSize = text.fontSize;
            text.horizontalOverflow = HorizontalWrapMode.Wrap;

            var button = rt.gameObject.AddComponent<Button>();
            button.targetGraphic = body;
            var colors = button.colors;
            colors.normalColor = Color.white;
            colors.highlightedColor = new Color(1.35f, 1.35f, 1.35f, 1f);
            colors.selectedColor = colors.highlightedColor;
            colors.pressedColor = new Color(1.7f, 1.7f, 1.7f, 1f);
            colors.disabledColor = new Color(0.75f, 0.75f, 0.75f, 1f);
            colors.colorMultiplier = 1f;
            colors.fadeDuration = 0.08f;
            button.colors = colors;
            button.onClick.AddListener(() => { GameAudio.Play(Sfx.Click); onClick(); });

            var press = rt.gameObject.AddComponent<MenuButton>();
            press.Init(button, content, group, glow, rim, iconImage, text);
            return press;
        }

        // ----- Kinds of button and shared screen parts -----

        /// <summary>Gold glowing main action, cyan option, quiet grey-blue (back, cancel), or red for leaving.</summary>
        public enum Kind { Primary, Secondary, Quiet, Danger }

        public static readonly Color Quiet = new Color(0.55f, 0.68f, 0.82f);

        public static Color AccentOf(Kind kind) =>
            kind == Kind.Primary ? Gold : kind == Kind.Secondary ? Cyan : kind == Kind.Danger ? Red : Quiet;

        private static float GlowOf(Kind kind) =>
            kind == Kind.Primary ? 0.55f : kind == Kind.Secondary ? 0.16f : kind == Kind.Danger ? 0.25f : 0f;

        /// <summary>A button of the given kind, centred on <paramref name="position"/> relative to <paramref name="anchor"/>.</summary>
        public static MenuButton Make(Transform parent, string label, MenuIcon? icon, Kind kind, Vector2 anchor, Vector2 position, Vector2 size, Action onClick)
        {
            var b = Button(parent, label, icon, AccentOf(kind), anchor, new Vector2(0.5f, 0.5f), position, size, GlowOf(kind), onClick);
            b.Pulse = kind == Kind.Primary;
            return b;
        }

        /// <summary>The standard Back button in a screen's bottom-left corner.</summary>
        public static MenuButton BackButton(Transform box, string label, Action onClick) =>
            Make(box, label, MenuIcon.Back, Kind.Quiet, new Vector2(0f, 0f), new Vector2(220f, 80f), new Vector2(300f, 96f), onClick);

        /// <summary>
        /// A full-screen page: a dark scrim over the demo match and a large framed panel with a title and an accent
        /// bar under it. Returns the panel; the title text is named "Title".
        /// </summary>
        public static RectTransform ScreenBox(RectTransform screen, string title, out Text titleText)
        {
            var scrim = screen.gameObject.AddComponent<Image>();
            scrim.sprite = ProceduralTextures.White();
            scrim.color = new Color(0.01f, 0.02f, 0.05f, 0.6f);
            var box = UiFactory.Rect("Box", screen, new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(1660f, 960f));
            Panel(box, Cyan);
            var titleRect = UiFactory.Rect("Title", box, new Vector2(0.5f, 1f), new Vector2(0.5f, 1f), new Vector2(0f, -22f), new Vector2(1400f, 90f));
            titleText = Heading(titleRect, title, 64, Color.white);
            var bar = UiFactory.Rect("Accent", box, new Vector2(0.5f, 1f), new Vector2(0.5f, 1f), new Vector2(0f, -112f), new Vector2(140f, 6f));
            var barImage = bar.gameObject.AddComponent<Image>();
            barImage.sprite = Fill;
            barImage.type = UnityEngine.UI.Image.Type.Sliced;
            barImage.pixelsPerUnitMultiplier = 10f;
            barImage.color = Gold;
            barImage.raycastTarget = false;
            return box;
        }

        /// <summary>A recessed dark field (behind values, list rows and text boxes).</summary>
        public static Image Recess(RectTransform rt, Color color, float roundness = 1.6f)
        {
            var image = rt.gameObject.AddComponent<Image>();
            image.sprite = Fill;
            image.type = UnityEngine.UI.Image.Type.Sliced;
            image.pixelsPerUnitMultiplier = roundness;
            image.color = color;
            return image;
        }

        /// <summary>A thin rounded outline drawn over a recessed field.</summary>
        public static Image Outline(RectTransform parent, Color color, float roundness = 1.6f)
        {
            var image = UiFactory.Stretch("Outline", parent).gameObject.AddComponent<Image>();
            image.sprite = Rim;
            image.type = UnityEngine.UI.Image.Type.Sliced;
            image.pixelsPerUnitMultiplier = roundness;
            image.color = color;
            image.raycastTarget = false;
            return image;
        }

        /// <summary>Label text for forms: bold, upright, soft white with a shadow.</summary>
        public static Text FieldLabel(RectTransform rt, string text, int size, TextAnchor anchor = TextAnchor.MiddleLeft)
        {
            var label = UiFactory.Text(rt, text, size, new Color(0.88f, 0.93f, 1f), anchor, outline: false);
            var shadow = rt.gameObject.AddComponent<Shadow>();
            shadow.effectColor = new Color(0f, 0f, 0f, 0.6f);
            shadow.effectDistance = new Vector2(0f, -3f);
            return label;
        }

        /// <summary>Colour for a character ring: gold when picked, slate otherwise.</summary>
        public static Color RingColor(bool selected) => selected ? Gold : new Color(0.2f, 0.27f, 0.38f);

        /// <summary>
        /// A round character portrait filling <paramref name="rt"/>: a dark disc, the portrait clipped to a circle, and a
        /// smooth ring on top. The ring covers the clip's edge, which a uGUI Mask can only cut with jagged pixels.
        /// Returns the ring, for recolouring when the character is picked.
        /// </summary>
        public static Image PortraitFrame(RectTransform rt, Texture portrait, Color ringColor, out RawImage image)
        {
            var back = UiFactory.Image(UiFactory.Stretch("Back", rt), new Color(0.02f, 0.04f, 0.08f, 1f), Disc);
            back.raycastTarget = false;
            var mask = UiFactory.Stretch("Mask", rt);
            mask.anchorMin = new Vector2(PortraitInset, PortraitInset);
            mask.anchorMax = new Vector2(1f - PortraitInset, 1f - PortraitInset);
            UiFactory.Image(mask, Color.white, Disc).raycastTarget = false;
            mask.gameObject.AddComponent<Mask>().showMaskGraphic = false;
            image = UiFactory.Stretch("Portrait", mask).gameObject.AddComponent<RawImage>();
            image.texture = portrait;
            image.raycastTarget = false;
            var ring = UiFactory.Image(UiFactory.Stretch("Ring", rt), ringColor, RingSprite);
            ring.raycastTarget = false;
            return ring;
        }

        /// <summary>A centred dialog panel over a dark scrim, with a heading; returns the panel.</summary>
        public static RectTransform Dialog(RectTransform screen, Vector2 size, Color accent, string heading, Color headingColor, int headingSize = 62)
        {
            UiFactory.Image(screen, new Color(0.01f, 0.02f, 0.05f, 0.72f));
            var box = UiFactory.Rect("Box", screen, new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f), Vector2.zero, size);
            Panel(box, accent);
            Heading(UiFactory.Rect("Heading", box, new Vector2(0.5f, 1f), new Vector2(0.5f, 1f), new Vector2(0f, -36f), new Vector2(size.x - 80f, 100f)),
                heading, headingSize, headingColor);
            return box;
        }

        /// <summary>A small upper-case caption that sits in front of a row of chips.</summary>
        public static Text Caption(Transform parent, string text, float x, float y, float width)
        {
            var label = UiFactory.Text(UiFactory.Rect(text, parent, new Vector2(0f, 1f), new Vector2(0f, 0.5f), new Vector2(x, y), new Vector2(width, 50f)),
                text, 24, Quiet, TextAnchor.MiddleLeft, outline: false);
            return label;
        }
    }

    /// <summary>
    /// One choice in a row of choices, all on show at once: a rounded pill that fills gold when picked.
    /// Anchored by its left edge, so a row is laid out by adding widths.
    /// </summary>
    public sealed class MenuChip
    {
        private static readonly Color OffFill = new Color(0.02f, 0.04f, 0.08f, 0.85f);
        private static readonly Color OffRim = new Color(0.35f, 0.5f, 0.68f, 0.5f);
        private static readonly Color OnText = new Color(0.1f, 0.07f, 0.02f);
        private static readonly Color OffText = new Color(0.88f, 0.93f, 1f);
        private const float Roundness = 1.3f;

        private readonly Image _fill, _rim;
        private readonly Text _label;

        public RectTransform Rect { get; }

        public MenuChip(Transform parent, string text, float x, float y, float width, float height, Action onClick)
        {
            Rect = UiFactory.Rect(text, parent, new Vector2(0f, 1f), new Vector2(0f, 0.5f), new Vector2(x, y), new Vector2(width, height));
            _fill = MenuStyle.Recess(Rect, OffFill, Roundness);
            _rim = MenuStyle.Outline(Rect, OffRim, Roundness);
            _label = UiFactory.Text(UiFactory.Stretch("Label", Rect), text, Mathf.RoundToInt(height * 0.42f), OffText, TextAnchor.MiddleCenter, outline: false);
            UiFactory.UseDisplayFont(_label);
            var button = Rect.gameObject.AddComponent<Button>();
            button.targetGraphic = _fill;
            var colors = button.colors;
            colors.highlightedColor = new Color(1.3f, 1.3f, 1.3f, 1f);
            colors.selectedColor = Color.white;
            colors.pressedColor = new Color(1.6f, 1.6f, 1.6f, 1f);
            colors.fadeDuration = 0.08f;
            button.colors = colors;
            button.onClick.AddListener(() => { GameAudio.Play(Sfx.Click); onClick(); });
        }

        public void SetOn(bool on)
        {
            _fill.color = on ? MenuStyle.Gold : OffFill;
            _rim.color = on ? MenuStyle.Gold : OffRim;
            _label.color = on ? OnText : OffText;
        }
    }

    /// <summary>
    /// A styled menu button's behaviour: squashes when pressed, slides in when its screen opens, pulses its glow
    /// if it is the main action, and dims when disabled.
    /// </summary>
    public sealed class MenuButton : MonoBehaviour, IPointerDownHandler, IPointerUpHandler, IPointerExitHandler
    {
        private Button _button;
        private RectTransform _content;
        private CanvasGroup _group;
        private Image _glow, _rim, _icon;
        private float _glowBase;
        private bool _pressed;
        private float _scale = 1f;
        private float _introDelay, _introTime = -1f;

        public Button Button => _button;
        public Text Label { get; private set; }
        /// <summary>Pulse the glow (for the main action).</summary>
        public bool Pulse { get; set; }

        public bool Interactable
        {
            get => _button.interactable;
            set { _button.interactable = value; if (_introTime < 0f) _group.alpha = value ? 1f : 0.55f; }
        }

        /// <summary>Recolours the rim, icon and glow (e.g. a Ready button turning grey once pressed).</summary>
        public void SetAccent(MenuStyle.Kind kind)
        {
            var accent = MenuStyle.AccentOf(kind);
            _rim.color = accent;
            if (_icon != null) _icon.color = accent;
            if (_glow != null)
            {
                _glow.color = new Color(accent.r, accent.g, accent.b, _glowBase);
                _glow.enabled = kind != MenuStyle.Kind.Quiet;
            }
            Pulse = kind == MenuStyle.Kind.Primary && _glow != null;
        }

        internal void Init(Button button, RectTransform content, CanvasGroup group, Image glow, Image rim, Image icon, Text label)
        {
            _rim = rim;
            _icon = icon;
            _button = button;
            _content = content;
            _group = group;
            _glow = glow;
            _glowBase = glow != null ? glow.color.a : 0f;
            Label = label;
        }

        /// <summary>Plays the slide-in after <paramref name="delay"/> seconds.</summary>
        public void Intro(float delay)
        {
            _introDelay = delay;
            _introTime = 0f;
            _group.alpha = 0f;
            _content.anchoredPosition = new Vector2(-70f, 0f);
        }

        /// <summary>Adds a small tag (e.g. "SOON") at the right end of the button.</summary>
        public void Tag(string text, Color color)
        {
            var rt = UiFactory.Rect("Tag", _content, new Vector2(1f, 0.5f), new Vector2(1f, 0.5f), new Vector2(-26f, 0f), new Vector2(118f, 44f));
            var bg = rt.gameObject.AddComponent<Image>();
            bg.sprite = MenuStyle.Fill;
            bg.type = Image.Type.Sliced;
            bg.pixelsPerUnitMultiplier = 1.6f;
            bg.color = new Color(color.r, color.g, color.b, 0.9f);
            bg.raycastTarget = false;
            var label = UiFactory.Text(UiFactory.Stretch("Text", rt), text, 26, new Color(0.04f, 0.06f, 0.1f), TextAnchor.MiddleCenter, outline: false);
            UiFactory.UseDisplayFont(label);
        }

        public void OnPointerDown(PointerEventData eventData) { if (_button.interactable) _pressed = true; }
        public void OnPointerUp(PointerEventData eventData) => _pressed = false;
        public void OnPointerExit(PointerEventData eventData) => _pressed = false;

        private void OnDisable()
        {
            _pressed = false;
            _scale = 1f;
            if (_content != null) _content.localScale = Vector3.one;
        }

        private void Update()
        {
            float dt = Time.unscaledDeltaTime;

            float target = _pressed ? 0.95f : 1f;
            _scale = Mathf.MoveTowards(_scale, target, dt * 1.2f);
            _content.localScale = new Vector3(_scale, _scale, 1f);

            if (_introTime >= 0f)
            {
                _introTime += dt;
                float t = Mathf.Clamp01((_introTime - _introDelay) / 0.42f);
                float ease = 1f - Mathf.Pow(1f - t, 3f);
                _content.anchoredPosition = new Vector2(-70f * (1f - ease), 0f);
                float full = _button.interactable ? 1f : 0.55f;
                _group.alpha = full * Mathf.Clamp01(t * 1.6f);
                if (t >= 1f) _introTime = -1f;
            }

            if (_glow != null && Pulse)
            {
                float wave = 0.5f + 0.5f * Mathf.Sin(Time.unscaledTime * 2.6f);
                var c = _glow.color;
                c.a = _glowBase * (0.65f + 0.55f * wave);
                _glow.color = c;
            }
        }
    }

    /// <summary>Fades and settles the logo in when the main menu opens, then lets it float gently.</summary>
    public sealed class MenuLogo : MonoBehaviour
    {
        private RectTransform _rect;
        private CanvasGroup _group;
        private Vector2 _home;
        private float _time = -1f;

        private void Awake()
        {
            _rect = (RectTransform)transform;
            _group = gameObject.AddComponent<CanvasGroup>();
            _group.blocksRaycasts = false;
            _home = _rect.anchoredPosition;
        }

        public void Intro() => _time = 0f;

        private void Update()
        {
            float bob = Mathf.Sin(Time.unscaledTime * 1.3f) * 5f;
            if (_time >= 0f)
            {
                _time += Time.unscaledDeltaTime;
                float t = Mathf.Clamp01(_time / 0.55f);
                float ease = 1f - Mathf.Pow(1f - t, 3f);
                // A slight overshoot, so the logo "lands".
                float scale = Mathf.LerpUnclamped(0.82f, 1f, ease) + Mathf.Sin(t * Mathf.PI) * 0.04f;
                _rect.localScale = new Vector3(scale, scale, 1f);
                _group.alpha = Mathf.Clamp01(t * 2f);
                if (t >= 1f) _time = -1f;
            }
            _rect.anchoredPosition = _home + new Vector2(0f, bob);
        }
    }
}
